window.MONSTER_CHUNK_149 = [{"name":"Slime Demodand","cr":13,"xp":25600,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demodand","evil","extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"120 ft."}],"auras":["stench (DC 21, 2d6 rounds)"],"ac":28,"ac_touch":14,"ac_flat_footed":24,"ac_mods":"+4 Dex, +14 natural","hp":136,"hd":"13d10+65","hdvalue":13,"fort":13,"ref":8,"will":10,"dr":"10/good and magic","immunities":["acid","poison","mindaffecting effects"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"sr":24,"speed":[{"type":"land","speed":40},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"2 claws +22 (1d6+8 plus 1d6 acid), bite +21 (1d8+8 plus 1d6 acid)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"enslime"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect good"},{"spell":"detect magic"},{"spell":"detect thoughts"},{"spell":"fear"},{"spell":"gaseous form"},{"spell":"invisibility","details":"self only"},{"spell":"magic circle against good"},{"spell":"see invisibility"},{"spell":"tongues"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 6, 1d4 tarry demodands 50%; or 1 slime demodand 20%"}]},{"frequency":"3/day","spells":[{"spell":"acid fog"},{"spell":"dispel magic"},{"spell":"fog cloud"},{"spell":"ray of enfeeblement"}]}],"strength":26,"dexterity":18,"constitution":20,"intelligence":14,"wisdom":14,"charisma":18,"baseatk":13,"cmb":21,"cmd":35,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Power Attack"},{"feat":"Sickening Critical"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":20},{"skill":"Fly","value":14},{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (planes)","value":18},{"skill":"Perception","value":22},{"skill":"Sense Motive","value":8},{"skill":"Spellcraft","value":18},{"skill":"Stealth","value":20},{"skill":"Survival","value":18}],"languages":["Abyssal","Common","Infernal"],"sq":[{"type":"slimy hide"}],"environments":["any (Tarterus)"],"organizations":["solitary","troupe (2-5)"],"treasure":"standard","description_visual":"This creature looks to be about 6 or 7 ft. tall. It appears as a bloated, slimy, black humanoid with large bat-like wings protruding from its shoulders. Its skin constantly drips and oozes a thick white-gray mucus. It has thick elephantine legs and long, powerful arms that end in razorsharp talons.","group":"Demodand","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Enslime","kind":"Ex","details":"If a slime demodand hits an opponent with all of its natural attacks in the same round, it deals an extra 1d6 points of acid damage (in addition to the acid damage dealt by its natural attacks)."},{"type":"Slimy Hide","kind":"Ex","details":"A slime demodand's hide is covered in acidic slime. Creatures attacking it unarmed or with natural weapons take 1d6 points of acid damage each time one of their attacks hits."}],"description":"Known as the middle class of the demodand race, slime demodands are as evil as their lesser relatives, the tarry demodands. They delight in torturing creatures of lesser skill and rank than themselves. A typical slime demodand stands 6 ft. tall and weighs 500 pounds. The slime demodand attacks with its claws and bite in combat. It often opens combat with a ray of enfeeblement targeted against the physically strongest (or perceived physically strongest) opponent.","ecology":"","habitat_society":"","credit":"The Slime Demodand originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Stygian Spawn","cr":13,"xp":25600,"alignment":"NE","size":"Huge","type":"outsider","subtypes":["aquatic","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":24,"ac_touch":10,"ac_flat_footed":22,"ac_mods":"+2 Dex, +14 natural, -2 size","hp":162,"hd":"13d10+91","hdvalue":13,"fort":18,"ref":10,"will":8,"dr":"10/good","resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":24,"speed":[{"type":"land","speed":40},{"type":"swim","speed":30}],"melee":"bite +21 (2d6+10), 2 claws +21 (1d8+10), tail slap +19 (1d8+5 plus grab) or tongue +22 touch (1d8+10 plus grab)","space":"15 ft.","reach":"15 ft. (30 ft. with tongue)","special_attacks":[{"type":"breath weapon","details":"60 ft. line, 10d6 sonic, DC 23 half, usable every 1d4 rounds"},{"type":"swallow whole","details":"6d6 acid damage, AC 17, 16 hp"},{"type":"tongue"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"3/day","spells":[{"spell":"magic circle against good"},{"spell":"unholy blight"}]}],"strength":31,"dexterity":15,"constitution":24,"intelligence":6,"wisdom":14,"charisma":16,"baseatk":13,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":37,"cmd_special":"+4 vs. trip","feats":[{"feat":"Critical Focus"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (tongue)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Intimidate","value":19},{"skill":"Knowledge (planes)","value":14},{"skill":"Perception","value":18},{"skill":"Stealth","value":16},{"skill":"Swim","value":18}],"languages":["Abyssal","Common","Infernal"],"sq":[{"type":"amphibious"}],"environments":["any (River Styx)"],"organizations":["solitary","pack (2-6)"],"treasure":"standard","description_visual":"This creature resembles a monstrous amphibian, with equal parts toad, newt, and salamander. Its smooth skin erupts here and there with hideous lesions, each one leaking a viscous ichor the color of mucus.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Tongue","kind":"Ex","details":"A Stygian spawn's tongue is a primary attack with a reach equal to twice the spawn's normal reach. A Stygian spawn's tongue is covered in sharpened barbs and any attempt to break free of a grapple with it, whether successful or not, deals an extra 1d6 points of piercing damage to the target. A Stygian spawn doesn't gain the grappled condition while using its tongue in this manner."}],"description":"A Stygian spawn is a creature that lurks along the banks of the River Styx. Unlike amphibians on the Material Plane, Stygian spawn spend very little time in the water. Most of the time, these vile creatures reside deep in the mud in a self-induced state of hibernation. Stygian spawns only eat creatures not native to the lower planes; such creatures are the spawns' only source of food. Travelers in the realms of the lower planes quickly learn to fear the horrid Stygian spawn, which awaken from their hibernation and erupt from the mud of the River Styx with surprising speed. A Stygian spawn summoned to another plane is dangerous to all life there, since it can eat any organic substance that fits in its mouth. Occasionally, Stygian spawn are awakened on purpose by bored charonadaemons who hunt the creatures for sport. Stygian spawn tadpoles are harmless, and resemble pale, boneless fish that swim mindlessly in the River Styx. These tadpoles are a frequent source of food for hungry hydrodaemons.\n\nA fully-grown Stygian spawn is 20 ft. long and weigh 3,000 pounds.\n\nSince their only source of food-extraplanar travelers-are so rare, Stygian spawn attack with their barbed tongue, trying to grapple and swallow their opponents as quickly as possible. In extended combats, however, a Stygian spawn blasts at opponents with its breath weapon.","ecology":"","habitat_society":""},{"name":"Water Elemental Construct","cr":13,"xp":25600,"alignment":"N","size":"Huge","type":"construct","subtypes":["elemental","extraplanar","water"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":27,"ac_touch":15,"ac_flat_footed":20,"ac_mods":"+7 Dex, +12 natural, -2 size","hp":205,"hd":"30d10+40","hdvalue":30,"fort":10,"ref":17,"will":10,"defensive_abilities":["water mastery"],"dr":"10/adamantine","immunities":["construct traits","elemental traits","magic"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":120}],"melee":"2 slams +39 (2d8+11)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"drench"},{"type":"engulf","details":"DC 36"}],"strength":33,"dexterity":24,"wisdom":11,"charisma":1,"baseatk":30,"cmb":43,"cmd":60,"skills":[{"skill":"Swim","value":19}],"environments":["any (Plane of Water)"],"organizations":["solitary"],"treasure":"none","description_visual":"A humanoid creature composed entirely of water and about 9 ft. tall moves silently across the ground, leaving trails of water in its path. Its watery head contain no discernable features.","group":"Elemental Construct","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Drench","kind":"Ex","details":"A water elemental construct's touch puts out torches, campfires, exposed lanterns, and other open flames of nonmagical origin if these are of Large size or smaller. The construct can dispel magical fire it touches as dispel magic (caster level equal's the elemental construct's HD)."},{"type":"Engulf","kind":"Ex","details":"A water elemental construct can simply engulf Large or smaller creatures in its path as a standard action. It cannot make a slam attack during a round in which it engulfs. The water elemental construct merely has to move over the opponents, affecting as many as it can cover. Opponents can make attacks of opportunity against the construct, but if they do so they are not entitled to a saving throw. Those who don't attempt attacks of opportunity can attempt a DC 36 Reflex save to avoid being engulfed—on a success, they are pushed back or aside (opponent's choice) as the construct moves forward. Engulfed creatures are in danger of suffocating, and are trapped within its body until they are no longer pinned. The save DC is Strength-based."},{"type":"Immunity to Magic","kind":"Ex","details":"A water elemental construct is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. A control water spell or cold effect slows a water elemental construct for 2d6 rounds with no saving throw. A horrid wilting spell deals 1d8 points of damage per caster level to a water elemental construct. The elemental construct can attempt a Fortitude save (DC 18 + caster's relevant ability modifier) for half damage. A create water spell heals 1d4 points of damage on the construct for each 2 gallons of water created."},{"type":"Water Mastery","kind":"Ex","details":"A water elemental construct gains a +2 bonus on attack and damage rolls if both it and its foe are touching water. If the opponent or the elemental construct is touching the ground, the elemental construct takes a -4 penalty on attack and damage rolls. (These modifiers are not included in the statistics block.)"}],"description":"Water elemental constructs are rare elemental constructs (perhaps as rare or rarer than fire elemental constructs) found in the palaces of the Water Elemental Princes or in the service of a powerful spellcaster or water deity. The are usually given the task of keeping secret or guarding an area underwater as this is their native environment and they don't function well outside of it. A water elemental construct is a humanoid, 9 ft. tall, composed of water. No discernable features can be seen on its head, though sometimes the face of an elemental spirit seems to appear randomly somewhere on its form. A water elemental construct crashes down on its opponents with watery fists before attempting to grab a foe and stuff it into its watery form. An engulfed foe is held until it drowns; thereafter, the elemental construct expels the creature's corpse onto the ground. Elemental constructs are used by powerful mages as servants, bodyguards, and assassins. An elemental construct, like any other automaton follows any order or command given to it to the best of its ability. An elemental construct's creator can command it if the construct is within 60 ft. and can see and hear its creator. If not commanded, an elemental construct usually follows its last instruction to the best of its ability, though if attacked it returns the attack. The creator can give the elemental construct a simple command to govern its actions in his or her absence. The elemental construct's creator can order the construct to obey the commands of another person (who might in turn place the elemental construct under someone else's control, and so on), but the elemental construct's creator can always resume control over his creation by commanding the elemental construct to obey him alone. Each elemental construct appears as a humanoid creature about 9 ft. tall and is composed entirely of its native element. Construction An elemental construct's body is formed completely of one of the four elements air, earth, fire, or water. The materials must be the finest quality or purest form taken from the respective plane and mixed with rare oils, powders, and other ingredients totaling 5,000 gp. ELEMENTAL CONSTRUCT CL 17th; Price 200,000 gp Requirements Craft Construct, geas/ quest, limited wish, two spells of 4th level or higher with the appropriate elemental descriptor, creator must be caster level 17th; Skill Craft (sculptures) DC 20; Cost 102,500 gp","ecology":"","habitat_society":""},{"name":"Widow Creeper","cr":13,"xp":25600,"alignment":"N","size":"Large","type":"plant","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"plantsense","modifier":"120 ft."}],"ac":28,"ac_touch":9,"ac_flat_footed":28,"ac_mods":"+19 natural, -1 size","hp":178,"hd":"17d8+102","hdvalue":17,"fort":15,"ref":7,"will":8,"dr":"15/magic and slashing","immunities":["plant traits"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"2 tentacles +20 (2d8+8 plus grab)","space":"10 ft.","reach":"10 ft. (20 ft. with tentacles)","special_attacks":[{"type":"entangle"},{"type":"fluid drain"}],"strength":27,"dexterity":10,"constitution":21,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":12,"cmb":21,"cmb_special":"+4 vs. grapple","cmd":31,"cmd_special":"+12 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception, Stealth)"},{"feat":"Toughness"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Climb","value":21},{"skill":"Perception","value":19},{"skill":"Stealth","value":5,"special":"+17 in forests"}],"sq":[{"type":"improved woodland stride"}],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature resembles a monstrous spider about twice the size of a human constructed of weeds, vines, and leaves. Two writhing tentacles sprout from its spider-like body, each ending in a sharpened point. An hourglass-shaped pattern of leaves and brush can be seen on its back.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Control Plants","kind":"Su","details":"A widow creeper can use control plants, as the spell (caster level 17th)."},{"type":"Entangle","kind":"Su","details":"As a standard action, up to a number of times per day equal to its Constitution modifier (minimum 1), a widow creeper can fire a mass of sticky, clinging vines and weeds to a range of 60 ft. at a single target. This requires the widow creeper to succeed on a ranged touch attack with a +11 bonus to hit. A creature hit by the vines is entangled. An entangled creature can break free and move half its normal speed by using a full-round action to make a DC 23 Escape Artist check or a DC 23 Strength check. The check DCs are Constitution-based."},{"type":"Fluid Drain","kind":"Ex","details":"A widow creeper can suck brain fluids from a living creature by making a successful grapple check. If it pins the foe, it drains brain fluid, dealing 1d4 points of Constitution damage and 1 point of Intelligence damage each round that it maintains the hold."},{"type":"Improved Woodland Stride","kind":"Su","details":"A widow creeper can move through any sort of undergrowth (natural thorns, briars, overgrown areas, and similar terrain) at its normal speed without taking damage or suffering other impairment. This includes thorns, briars, and overgrown areas that are magically manipulated to impede motion."},{"type":"Plantsense","kind":"Ex","details":"A widow creeper can automatically pinpoint the location of anything within 120 ft. that is in contact with vegetation."}],"description":"Widow creepers are spider-like plant creatures that make their lairs deep in tangled forests. They constantly harass woodsmen, foresters, and denizens of the forests from their weed-like webs which they spin high in the tree tops. Widow creepers spend much of their time in their nests, venturing forth only to feed, and even then, they rarely venture far from their lair. They prefer to lure potential prey to them by rustling nearby leaves or underbrush. A widow creeper sustains itself on a diet of brain fluid and blood. Corpses drained of blood and fluids are left where they fall; the widow creeper doesn't devour the flesh, bones, or muscle of its prey. A widow creeper is 8 ft. tall and looks like a giant black widow formed from leaves, weeds, and tangled brush. It is dark greenish-brown in color. Two long, sinewy vine-like tentacles protrude from its body and aid the creature in capturing and securing its prey. A widow creeper utters no sounds and cannot speak any known languages. Widow creepers are ambush hunters, waiting in their vine-like webs for a creature to pass nearby. When a potential meal comes close to its nest the widow creeper leaps from hiding and attacks. It uses its tentacles to either slash its foe or grapple it. Against a grappled foe, a widow creeper stabs one of its long tentacles into the opponent's head and attempts to drain its brain fluids. While grappling a foe, the widow creeper uses its control plants and entangle attacks to keep any other opponents at bay.","ecology":"","habitat_society":""},{"name":"Woolly Rhinoceros Elasmotherium","cr":13,"xp":25600,"alignment":"N","size":"Large","type":"animal","init":0,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+10 natural, -1 size","hp":172,"hd":"15d8+105","hdvalue":15,"fort":17,"ref":9,"will":6,"speed":[{"type":"land","speed":30}],"melee":"gore +21 (2d6+15/19-20)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"powerful charge","details":"gore, 8d6+24"},{"type":"trample","details":"1d6+15, DC 27"}],"strength":31,"dexterity":10,"constitution":23,"intelligence":2,"wisdom":13,"charisma":2,"baseatk":11,"cmb":22,"cmb_special":"+2 vs. bull rush","cmd":32,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (gore)"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Focus (gore)"}],"skills":[{"skill":"Perception","value":25}],"environments":["cold forests","any marshes","any plains","temperate forests"],"organizations":["solitary","herd (2-8)"],"treasure":"none","description_visual":"This creature has massive legs and a stout body with a thick coat of brown fur. From the tip of its elongated nose rise two curving horns.","group":"Rhinoceros","source":"Tome of Horrors Complete (3pp)","description":"The elasmotherium stands as tall and as long as an elephant, averaging almost 15 ft. long and weighing around four tons. Its fur is thick, and its underlying body is tough and very resilient. Its single horn is thick, ivory colored, and almost six ft. long. Its fur tends to be a bit darker than the common woolly rhino's. Like its brethren, its eyesight is poor, thus it too relies on its keen sense of hearing and smell. The elasmotherium is a herding creature and encounters with herds are common. When danger presents itself, the females encircle the young, while the males charge the predator, goring with its horn.","ecology":"","habitat_society":""},{"name":"Ancient Dungeon Dragon","cr":14,"xp":38400,"alignment":"N","size":"Huge","type":"dragon","subtypes":["shapechanger"],"init":3,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (300 ft., DC 23)"],"ac":35,"ac_touch":7,"ac_flat_footed":35,"ac_mods":"-1 Dex, +28 natural, -2 size","hp":218,"hd":"19d12+95","hdvalue":19,"fort":16,"ref":10,"will":18,"dr":"15/magic","immunities":["enchantment spells and effects","paralysis","sleep"],"sr":25,"speed":[{"type":"land","speed":30},{"type":"fly","speed":200,"maneuverability":"poor"}],"melee":"bite +28 (2d8+16), 2 claws +28 (2d6+11), 2 wings +26 (1d8+5), tail slap +26 (2d6+16)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"100 ft. line or 50 ft. cone, DC 25, confusion 1d6 rounds"},{"type":"crush"}],"spell_like_abilities_caster_level":19,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"charm person"},{"spell":"detect thoughts"},{"spell":"mass suggestion"},{"spell":"suggestion"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":14,"spellsknown_concentration":19,"spellsknown":[{"spell_level":7,"spell_slots":3,"spells":[{"spell":"mass hold person"}]},{"spell_level":6,"spell_slots":5,"spells":[{"spell":"antimagic field"},{"spell":"greater dispel magic"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"persistent image"},{"spell":"prying eyes"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"arcane eye"},{"spell":"detect scrying"},{"spell":"illusory wall"},{"spell":"lesser globe of invulnerability"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"arcane sight"},{"spell":"deep slumber"},{"spell":"dispel magic"},{"spell":"major image"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"arcane lock"},{"spell":"magic mouth"},{"spell":"make whole"},{"spell":"phantom trap"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"hold portal"},{"spell":"shield"},{"spell":"silent image"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":33,"dexterity":9,"constitution":20,"intelligence":20,"wisdom":20,"charisma":18,"baseatk":19,"cmb":32,"cmd":41,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Craft Wondrous Item","type":"bonus"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Master Craftsman","type":"bonus"},{"feat":"Multiattack"},{"feat":"Skill Focus (Bluff)"},{"feat":"Persuasive"},{"feat":"Skill Focus (Craft [crystal carving])"},{"feat":"Skill Focus (Knowledge [engineering])"}],"skills":[{"skill":"Bluff","value":32},{"skill":"Craft (crystal carving)","value":24},{"skill":"Craft (traps)","value":17},{"skill":"Diplomacy","value":21},{"skill":"Disable Device","value":14},{"skill":"Fly","value":13},{"skill":"Intimidate","value":6},{"skill":"Knowledge (arcana)","value":27},{"skill":"Knowledge (dungeoneering)","value":27},{"skill":"Knowledge (engineering)","value":33},{"skill":"Linguistics","value":27},{"skill":"Perception","value":35},{"skill":"Sense Motive","value":31},{"skill":"Spellcraft","value":27}],"languages":["24 languages (except Druidic)","plus Common and Draconic"],"sq":[{"type":"change shape","details":"alter self"},{"type":"craft crystal ball"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"triple standard plus crystal ball","description_visual":"This dragon has a long serpentine neck, small wings, and glistening scales. Two small horns dominate its triangular head. Its body is gray in color, with scales tipped in flecks of gold and green. Its eyes are rounded and gray.","group":"Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A dungeon dragon's breath weapon is a line or cone of warm mist. Creatures caught in the area must succeed on Fortitude save or be affected as if by a confusion spell for 1d6 rounds."},{"type":"Change Shape","kind":"Su","details":"At will, a very young or older dungeon dragon can assume the form of any Small or Medium humanoid creature (as the alter self spell). It can remain in its humanoid form indefinitely. It cannot take the form of a specific individual."},{"type":"Craft Crystal Ball","kind":"Ex","details":"Dungeon dragon parents begin teaching their wyrmlings the necessary skills and spells to craft a crystal ball soon after they leave the egg. A dungeon dragon gains the Master Craftsman feat for free as a bonus feat without having to meet the prerequisites."},{"type":"Craft Wondrous Item","kind":"Ex","details":"Older dungeon dragons create new crystal balls with additional powers as they grow in intelligence and spellcasting ability. A young adult dungeon dragon gains the Craft Wondrous Item feat for free as a bonus feat."},{"type":"Dominate Monster","kind":"Sp","details":"A great wyrm dungeon dragon can use this ability three times per day. It works as a dominate monster spell. This ability is the equivalent of an 8th-level spell. Skills Dungeon dragons gain a +4 bonus to Perception checks. Spell-like Abilities A dungeon dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. Young-charm person; Juvenile-detect thoughts; Adult-suggestion; Old-charm monster; Ancient-mass suggestion; Great Wyrm-mass charm monster. The dungeon dragon uses these abilities to populate its dungeon with monsters it encounters in the surrounding terrain."}],"description":"The dungeon dragon is a curious creature that gets amusement by watching other beings engaged in life and death struggles. To this end, a dungeon dragon sets up a labyrinthine lair, setting traps and populating it with monsters. Younger dungeon dragons tend to lair in natural caverns to ease the burden of construction. Older, more experienced dungeon dragons have been known to construct their own sprawling subterranean complexes, even to the point of hiring on dwarf work gangs and swearing them to secrecy. Once the construction and refurbishing of its lair is complete, the dungeon dragon transforms itself into a humanoid and ventures into the surrounding countryside. There it spreads rumors and tales of this horrible catacomb in hopes of luring adventurers forth so it may watch them via its crystal ball. Young dungeon dragons often spend years living among humanoids, even to the point of joining adventurers involved in dungeon delves. On such adventures, the intrepid dungeon dragon takes notes regarding the devious traps and monsters it encounters so that it can add such things to its own lair. Oddly enough, although a dungeon dragon goes to great pains to amass a treasure hoard, it cares little for material wealth. Rather, it uses the treasure it gathers as bait in its dungeon to lure in adventurers and provide it the entertainment it so greatly desires. Watching adventurers explore its catacomb is the only real treasure a dungeon dragon desires. The only material possession a dungeon dragon will risk its life to save is its crystal ball. Without this vital piece of equipment, all of the dragon's labor is in vain. A dungeon dragon in its natural form prefers to flee any combat. It likes to watch other creatures engaged in fights for life, not itself. If forced into melee, it swats at opponents with its powerful claws and bite. A dungeon dragon is proficient in the use of all simple and martial weapons and light and medium armor and shields.","ecology":"","habitat_society":""},{"name":"Chalkydri","cr":14,"xp":38400,"alignment":"NG","size":"Medium","type":"outsider","subtypes":["angel","extraplanar","good"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"see invisibility"}],"auras":["protective aura"],"ac":30,"ac_touch":17,"ac_flat_footed":27,"ac_mods":"+3 Dex, +13 natural, +4 sacred | +4 deflection vs. evil","hp":126,"hd":"12d10+60","hdvalue":12,"fort":13,"ref":11,"will":10,"save_mods":"+4 vs. poison, +4 vs. evil","dr":"10/evil","immunities":["acid","cold","petrification","death effects"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":25,"speed":[{"type":"land","speed":40},{"type":"fly","speed":90,"maneuverability":"good"}],"melee":"+2 flaming longsword +21 (1d8+8 plus 1d6 fire)","ranged":"+2 flaming javelin +17 (1d6+8 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"aid"},{"spell":"bless"},{"spell":"consecrate"},{"spell":"continual flame"},{"spell":"discern lies"},{"spell":"dispel evil"},{"spell":"dispel magic"},{"spell":"fog cloud"},{"spell":"holy smite"},{"spell":"invisibility","details":"self only"},{"spell":"plane shift"},{"spell":"remove curse"},{"spell":"remove disease"},{"spell":"remove fear"}]},{"frequency":"1/day","spells":[{"spell":"heal"},{"spell":"raise dead"},{"spell":"summon","details":"level 8, 1d4 movanic devas 35%"}]},{"frequency":"3/day","spells":[{"spell":"atonement"},{"spell":"cure serious wounds"},{"spell":"flame strike"},{"spell":"greater restoration"},{"spell":"holy word"},{"spell":"polymorph","details":"self only"}]}],"strength":23,"dexterity":16,"constitution":20,"intelligence":18,"wisdom":18,"charisma":19,"baseatk":12,"cmb":18,"cmd":35,"feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (longsword)"},{"feat":"Iron Will"}],"skills":[{"skill":"Diplomacy","value":19},{"skill":"Fly","value":22},{"skill":"Heal","value":19},{"skill":"Intimidate","value":16},{"skill":"Knowledge (planes)","value":19},{"skill":"Knowledge (religion)","value":16},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":23},{"skill":"Stealth","value":18},{"skill":"Survival","value":19}],"languages":["Celestial","Common","Draconic","Infernal","truespeech"],"environments":["any good-aligned plane"],"organizations":["solitary"],"treasure":"double standard","description_visual":"This angelic-looking creature resembles a muscular humanoid with coppery skin and coppery eyes. It has four large feathery wings of white and carries a longsword swathed in fire.","group":"Angel","source":"Tome of Horrors Complete (3pp)","description":"Chalkydris spend most of their time on the Ethereal or Astral Plane or on one of the many Elemental Planes, usually acting on behalf of some deity of good. Chalkydris are militaristic and often lead small retinues of other celestials against the infernal armies. When not serving in such roles, they are found acting as protectors or escorts to visitors on the good-aligned planes. Sometimes, a chalkydri is sent to the Material Plane by its deity to watch over a favored worshipper. When traveling the Material Plane, the chalkydri often takes a form more acceptable to humanoids.\n\nChalkydris appear as powerful, agile humans 6 to 7 ft. tall with coppery skin, red or blonde hair, and copper-colored eyes. Two sets of large feathery wings (four wings total) protrude from their back at shoulder level. Their wings are glossy white with copper tips. Chalkydris wear tunics or robes of varying colors, usually crimson, copper, green, silver, or gold.\n\nChalkydris enjoy combat and one is never without its +2 flaming longsword and at least two +2 flaming javelins. A chalkydri opens combat by hurling one of its javelins at a foe before moving into melee to battle with its longsword. While in combat, it utilizes its spell-like abilities to their fullest extent. If a chalkydri is overwhelmed in battle, it summons celestials to its aid or uses its plane shift ability to escape. If slain, the chalkydri's weapons explode in a blinding flash of fire.","ecology":"","habitat_society":"","gear":"+2 flaming longsword, 2 +2 flaming javelins"},{"name":"Dark Matter Entropic Ooze","cr":14,"xp":38400,"alignment":"N","size":"Huge","type":"ooze","subtypes":["extraplanar"],"init":-3,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"soulsight","modifier":"120 ft."}],"ac":13,"ac_touch":5,"ac_flat_footed":13,"ac_mods":"-3 Dex, +8 natural, -2 size","hp":391,"hd":"27d8+270","hdvalue":27,"fort":19,"ref":6,"will":9,"save_mods":"Will: +2 vs. charm effects","immunities":["negative energy","ooze traits"],"sr":24,"sr_mods":"vs. positive energy","speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"slam +28 (2d8+15 plus energy drain)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"devour soul"},{"type":"energy drain","details":"3 levels, DC 23"}],"strength":31,"dexterity":4,"constitution":30,"wisdom":1,"charisma":10,"baseatk":20,"cmb":32,"cmd":39,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":18}],"environments":["any (Plane of Negative Energy)"],"organizations":["solitary"],"treasure":"none","description_visual":"This protoplasmic creature resembles a giant amoeba, black in color. A deathly cold seems to emanate from its form.","group":"Ooze","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Devour Soul","kind":"Su","details":"A living creature slain by an entropic ooze has its soul devoured by the ooze. Such a creature cannot be returned to life until the entropic ooze that contains its soul is slain."},{"type":"Soulsight","kind":"Su","details":"An entropic ooze can automatically detect the location of any living creature within 120 ft. It also senses the strength of their life force automatically, as if it had cast deathwatch."}],"description":"A larger, more powerful version of the standard entropic ooze is know as the dark matter entropic ooze, a massive creature that rarely leaves its home plane. Spellcasters who summon this creature often live (or don't live) to regret it.","ecology":"","habitat_society":""},{"name":"Furnace Golem","cr":14,"xp":38400,"alignment":"N","size":"Huge","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":29,"ac_touch":7,"ac_flat_footed":29,"ac_mods":"-1 Dex, +22 natural, -2 size","hp":144,"hd":"19d10+40","hdvalue":19,"fort":6,"ref":5,"will":6,"dr":"15/adamantine","immunities":["construct traits","fire","magic","rust"],"resists":[{"type":"cold","value":20}],"speed":[{"type":"land","speed":20}],"melee":"2 slams +28 (4d6+11 plus 2d6 fire plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon","details":"50-ft. line, 10d6 fire, Reflex DC 19 half, every 1d4 rounds"},{"type":"furnace-interior"},{"type":"heat"}],"strength":32,"dexterity":9,"wisdom":11,"charisma":1,"baseatk":19,"cmb":32,"cmb_special":"+4 vs. grapple","cmd":41,"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This 20-foot tall construct looks like a humanoid clad in black iron armor. A large grate-covered opening in its abdomen houses a roaring fire in its innards.","group":"Golem","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Furnace-Interior","kind":"Ex","details":"A furnace golem can try to shove a grabbed opponent up to two sizes smaller than itself into its interior by making a successful grapple check. An opponent thrown into the furnace golem's interior is trapped as a metal grating closes over the opening in the same round. A trapped creature automatically takes 2d6 points of fire damage each round. Escaping the creature's interior requires a successful Strength check (DC 30) to bend the bars. Alternately a trapped creature can escape by dealing at least 25 points of damage to the bars (AC 22). Note, the golem's damage reduction applies to all attacks against the bars. A Huge furnace golem's interior can hold 2 Medium, 8 Small, or 16 Tiny or smaller creatures."},{"type":"Heat","kind":"Ex","details":"A furnace golem's entire form is extremely hot. Any slam attack deals fire damage. Creatures attacking a furnace golem unarmed or with natural weapons take this same fire damage each time one of their attacks hits."},{"type":"Immunity to Magic","kind":"Ex","details":"A furnace golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature as noted below. A magical attack that bypasses its cold resistance slows a furnace golem (as the slow spell) for 3 rounds, with no saving throw. A magical attack that deals fire damage breaks any slow effect on the furnace golem and heals 1 point of damage for each 3 points of damage the attack would otherwise deal. If the amount of damage would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points."}],"description":"Furnace golems are most often used to guard some arcane secret or treasure, though some are programmed to seek out objects or individuals. Those used as guards stand motionless, appearing as nothing more than a giant black iron statue, until activated. Furnace golems, like other constructs, obey their creator's commands to the best of their ability. Should the creator die, or should the golem's commands be unattainable, the furnace golem becomes rogue. That is, it is still completely functional but follows no commands or orders from anyone. Furnace golems open combat using their breath weapon before moving to pulverize their opponents with their massive fists. Grabbed opponents are shoved into the golem's burning interior where they are trapped until they break free or die. The fires powering a furnace golem are magical in nature, i.e. it needs no source of natural fuel to power it and they cannot be extinguished, though if a furnace golem is destroyed, the fires in its innards burn out. Construction A furnace golem's body is constructed from 8,000 pounds of iron mixed with rare ingredients and chemicals totaling 12,000 gp. FURNACE GOLEM CL 16th; Price 180,000 gp Requirements Craft Construct, fireball, geas/quest, limited wish, polymorph any object, wall of fire, creator must be caster level 16th; Skill Craft (armor or weapons) DC 20; Cost 96,000 gp","ecology":"","habitat_society":""},{"name":"Gharros Demon","cr":14,"xp":38400,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":28,"ac_touch":13,"ac_flat_footed":24,"ac_mods":"+4 Dex, +15 natural, -1 size","hp":248,"hd":"16d10+160","hdvalue":16,"fort":20,"ref":14,"will":9,"dr":"15/cold iron and good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":25,"speed":[{"type":"land","speed":30}],"melee":"battleaxe +25 (2d6+10/19-20/x3) or  battleaxe +25 (2d6+10/19-20/x3), 2 stings +26 (1d8+10/19-  20  plus poison)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"desecrate"},{"spell":"detect good"},{"spell":"detect magic"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"mirror image"},{"spell":"telekinesis"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 6, 4d10 dretches, 1d4 vrocks, or 1d2 glabrezus 50%; or 1 gharros 20%"}]}],"strength":31,"dexterity":18,"constitution":30,"intelligence":18,"wisdom":18,"charisma":20,"baseatk":16,"cmb":27,"cmd":41,"cmd_special":"+8 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Critical (tail sting)"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (sting)"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Bluff","value":24},{"skill":"Climb","value":29},{"skill":"Diplomacy","value":21},{"skill":"Escape Artist","value":20},{"skill":"Intimidate","value":24},{"skill":"Knowledge (planes)","value":20},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":15},{"skill":"Spellcraft","value":14},{"skill":"Stealth","value":13},{"skill":"Survival","value":23}],"languages":["Abyssal","Common","any three","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","pack (2-4)"],"treasure":"standard","description_visual":"This hideous creature appears to be half-scorpion and half-human. Its upper torso is that of a greenish-silver humanoid with long, flowing dark hair and stark white eyes while its lower torso is that of a reddish-brown scorpion. Its tail splits into two separate stingers and the creature's mouth is filled with razor-sharp teeth.","group":"Demon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 28; frequency 1/round for 6 rounds; effect 1d4 Con damage; cure 1 save."}],"description":"A gharros looks like a cross between a large human and an even larger scorpion. They serve as guards, soldiers, shock troops (and even assassins sometimes) to some of the minor nobles and lesser demon lords of the Abyss. They hate all goodness and seek to destroy it at any opportunity through whatever means available.\n\nA gharros is about 8 ft. tall and 10 ft. long and weighs around 1,500 pounds.\n\nGharros are very aggressive in battle and seek to kill the strongest opponent first. They wield their battleaxes in combat and sting with their deadly tails, all the while sprinkling the fight with their spell-like abilities.\n\nUnless ordered to do so, gharros never take prisoners in battle. They fight to the death (either their death or their opponent's).","ecology":"","habitat_society":"","gear":"battleaxe"},{"name":"Noble Time Elemental","cr":14,"xp":38400,"alignment":"N","size":"Large","type":"outsider","subtypes":["elemental","extraplanar","time"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":25,"ac_touch":19,"ac_flat_footed":19,"ac_mods":"+5 Dex, +1 dodge, +4 insight, +6 natural, -1 size","hp":190,"hd":"20d10+80","hdvalue":20,"fort":10,"ref":19,"will":18,"defensive_abilities":["foresight"],"dr":"15/-","immunities":["elemental traits","temporal magic"],"sr":25,"speed":[{"type":"fly","speed":20,"maneuverability":"perfect"}],"melee":"2 slams +24 (2d6+4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"alter age","details":"1/day, Fort DC 24"},{"type":"multi-manifestation"},{"type":"temporal displacement","details":"3/day, 20 minutes, Fort DC 24"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"time stop"}]}],"strength":18,"dexterity":20,"constitution":18,"intelligence":18,"wisdom":18,"charisma":15,"baseatk":20,"cmb":25,"cmd":45,"feats":[{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (slam)"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Diplomacy","value":22},{"skill":"Fly","value":34},{"skill":"Knowledge (arcana)","value":27},{"skill":"Knowledge (history)","value":27},{"skill":"Knowledge (local)","value":27},{"skill":"Knowledge (planes)","value":27},{"skill":"Perception","value":33},{"skill":"Sense Motive","value":27},{"skill":"Stealth","value":24},{"skill":"Survival","value":27}],"languages":["telepathy 100 ft."],"sq":[{"type":"time jaunt","details":"Will DC 24"}],"environments":["any (Plane of Time)"],"organizations":["solitary","troupe (noble plus 1-2 common time elementals)","court (royal plus 1-2 nobles and 1-4 common time elementals)"],"treasure":"none","description_visual":"This creature appears as a formless cloud of yellowish-red vapor or dust about 5 ft. in diameter.","group":"Elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Alter Age","kind":"Su","details":"Once per day, a noble time elemental can age a creature simply by touching it (this requires a melee touch attack). If successful, the target must succeed on a Fortitude save or advance forward one aging step (from adulthood to middle age, from middle age to old, from old to venerable, and so on). If a character ages, he takes all the effects to his physical ability scores, but doesn't gain any of the bonuses to his mental ability scores. A venerable creature affected by this ability dies (from massive cell death) and cannot be restored to life by mortal magic. The save DC is Constitution-based. Alternately, a time elemental can use its alter age ability to reduce a character's age. If the target is unwilling, the time elemental must succeed on a melee touch attack. An unwilling target can make a Fortitude save to avoid the effects. If the save fails, the target ages one age step backwards (from middle age to adulthood for example) and gains all bonuses to physical ability scores from his new age (simply flip the penalties listed on the aging table into an equal numbered bonus). A character that regresses in age doesn't reduce its mental ability scores. This ability doesn't affect a character that has died from old age. A time elemental can also use this ability to age vegetable matter 10-200 years (older or younger) or mineral matter 100-2,000 years (older or younger). Royal time elementals can use this ability twice per day."},{"type":"Cell Death","kind":"Ex","details":"Damage dealt by a time elemental's slam attack doesn't heal naturally (but it can still be healed magically). Additionally, a creature slain by a time elemental can only be raised through the successful casting of a miracle, true resurrection, or wish spell."},{"type":"Foresight","kind":"Su","details":"A time elemental can see a few seconds into the future. This ability prevents it from being surprised, caught flat-footed, or flanked. It also grants the time elemental an insight bonus to AC equal to its Wisdom bonus. This ability can be negated, but the time elemental can restart it as a free action on its next turn."},{"type":"Immunity to Temporal Magic","kind":"Ex","details":"Time elementals are immune to all time-related spells and effects (including time stop, temporal stasis, and the like). Note, the time stop ability of the noble and royal time elementals can affect those time elementals of lesser power (i.e., a noble can affect a common and a royal can affect a noble or common)."},{"type":"Multi-Manifestation","kind":"Su","details":"A time elemental exists in several other dimensions at any given time. As a standard action, it can bring forth 1d4 of these manifestations to its current locale in order to gain multiple attacks that round. Treat each manifestation as a separate time elemental with hit points equal to the time elemental's current hit points. A manifestation cannot use any of the supernatural or spell-like abilities of the time elemental (a manifestation does however gain the time elemental's foresight ability). A time elemental cannot have more than four manifestations present at one time. Because each manifestation is a part of the time elemental that called them, a successful attack on the time elemental or any of its manifestations deals an equal amount of damage to them all."},{"type":"Summon Time Elementals","kind":"Sp","details":"Once per day, a royal time elemental can attempt to summon 1d4 common time elementals with a 70% chance of success or 1-2 noble time elementals with a 30% chance of success. This ability is the equivalent of a 9th-level spell."},{"type":"Temporal Displacement","kind":"Su","details":"By making a melee touch attack against a foe, a noble or royal time elemental can remove that creature from the current time stream if it fails a Fortitude save. The save is Constitution-based. On a failed save, the creature disappears in a flash of white energy. For a number of minutes equal to the time elemental's Hit Dice, the displaced creature is effectively nonexistent. No form of magic, effect, or force can detect or aid such a creature. A displaced creature can attempt a Wisdom check (DC equal to the initial Fort DC) on its turn to break the effects and end the displacement. The save is Constitution-based. When the effect ends, the creature reappears in the same space it was in before being displaced. If the space is occupied when the creature returns, it is shunted aside to the first open space and takes no damage. A noble or royal time elemental can use this ability three times per day."},{"type":"Time Jaunt","kind":"Su","details":"A time elemental can slip through the time stream and appear anywhere on the same plane of existence as if by greater teleport. This ability transports the time elemental and up to four other creatures within a 30-foot radius. Unwilling creatures can attempt a Will save to avoid being carried away. This ability is otherwise similar to the spell of the same name (caster level equal to the elemental's HD). The save DC is Constitution-based."},{"type":"Time Stop","kind":"Sp","details":"Noble and royal time elementals can create an effect identical to a time stop spell once per day (caster level equals the time elemental's HD)."}],"description":"Time elementals are creatures from a plane most sages are unaware even exists. A time elemental is a powerful creature formed of pure time and matter such as is unknown to even the most learned of sages. It is unknown how or why time elementals enter the Material Plane, as they cannot be summoned using the standard summoning spells. Time elementals attack by forming misty or smoky arms from their forms and lashing at opponents or by spraying a fine mist onto their opponents so as to induce aging. Against particularly powerful opponents, a time elemental uses its alter age ability or (if of the royal sort) summons additional time elementals to its aid.","ecology":"","habitat_society":"","credit":"The Time Elemental originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Sand Giant","cr":14,"xp":38400,"alignment":"NE","size":"Huge","type":"humanoid","subtypes":["earth","giant"],"init":1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":24,"ac_touch":9,"ac_flat_footed":23,"ac_mods":"+3 armor, +1 Dex, +12 natural, -2 size","hp":218,"hd":"19d8+114 (+19)","hdvalue":19,"fort":17,"ref":7,"will":9,"defensive_abilities":["rock catching"],"speed":[{"type":"land","speed":40}],"melee":"greatsword +24 (4d6+16) or 2 slams +23 (2d6+11)","ranged":"rock +14 (2d6+16)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"fist of sand","details":"slam +26, 1d8+10 damage; DC 29; CMB +26, CMD 36; AC 20, touch 8, flat-footed 20; hp 69; 19 rounds"},{"type":"rock throwing","details":"120 ft."}],"spell_like_abilities_caster_level":19,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"earthquake"}]},{"frequency":"2/day","spells":[{"spell":"move earth"},{"spell":"soften earth and stone"}]}],"strength":33,"dexterity":13,"constitution":23,"intelligence":12,"wisdom":12,"charisma":14,"baseatk":14,"cmb":27,"cmb_special":"+2 vs. bull rush","cmd":38,"cmd_special":"+2 vs. bull rush","feats":[{"feat":"Alertness"},{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (greatsword)"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Perception","value":27},{"skill":"Survival","value":23}],"languages":["Common","Giant"],"sq":[{"type":"weapon and armor proficiency"}],"environments":["warm deserts"],"organizations":["solitary","gang (2-4)","raiding party (6-9 plus 1 cleric or sorcerer of 6th-9th level)","family (2-4 plus 35% noncombatants)","tribe (8-27 plus 35% noncombatants and 1 sorcerer of 10th-12th level and 1 cleric of 9th-11th level)"],"treasure":"standard","description_visual":"This giant looks like a savage humanoid with dark tan skin, dark hair, and green eyes.","group":"Giant","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Fist of Sand","kind":"Su","details":"Once per day as a move action, a sand giant can form a volume of sand within 40 ft. into the shape of a 20-foot long arm that ends in a clenched fist. The arm is Huge and has a space of 15 ft. and a reach of 20 ft. The arm and fist cannot move from the location where it was created. The sand giant can order the arm to attack a target as a move action. Once given a target, the arm automatically attacks that target on the giant's turn. The arm remains for a number of rounds equal to the sand giant's Hit Dice (19 rounds for a typical sand giant). A sand giant doesn't need to concentrate to maintain the arm and can direct it to attack a new target or adapt a new tactic as a free action. The arm's base attack bonus is equal to that of the giant that created it, and it deals slam damage equal to the slam attack for a creature of its size (Huge). Any creature struck must succeed on a DC 29 Fortitude save or be stunned for 1 round. The save DC is Strength-based, using the HD of the sand giant and the Strength of the fist of sand. The arm has an AC of 20 (+12 natural, -2 size) and has hit points equal to three times the Constitution score of the sand giant that created it. It has a Strength score of 30. The arm loses shape if it is reduced to 0 or less hit points, the duration expires, or the sand giant dies."},{"type":"Weapon and Armor Proficiency","kind":"Ex","details":"Sand giants are automatically proficient with simple weapons, martial weapons, light and medium armor, and shields."}],"description":"Sand giants are brutal, somewhat barbaric giants that prey on those weaker than themselves. They have dark tan skin, brown hair, and dark brown or dark green eyes. An adult male stands approximately 20 ft. tall. Males tend to wear their hair and beards braided. Sand giants wear light clothes and light armor (if any). In times of battle or war, males may don chainmail. A typical sand giant's bag contains food, 3d4 mundane items, and a modest amount of cash (no more than 12d10 coins). Sand giants can live to be 500 years old. Sand giants make their homes in warm desert lands away from civilization. They live in organized tribes consisting of 8-9 families of 2-4 members each. On occasion, a tribe forms a raiding party that sets off to the nearest civilized place, returning at a later time with food, coins, and captives. For each adult in a sand giant's lair, there is a 40% chance that the lair has 1d3 captives of any humanoid race. Sand giants favor their greatswords in combat. They usually begin combat by shaping a fist from the surrounding terrain and attacking with their greatswords in concert with the earthen fist. Sand giant don't throw rocks like many other giants do, but they can catch rocks or similar projectiles as other giants.","as_character":[{"description":"Sand giants are combative, and most are fighters. Many tribes or groups include druids or clerics with access to two of the following domains Earth, Evil, Strength, and War.","racial_traits":[{"type":"Ability Score Bonuses","value":"+22 Strength, +2 Dexterity, +12 Constitution, +2 Intelligence, +2 Wisdom, +4 Charisma"},{"type":"Huge","value":"Sand giants are Huge and take a -2 penalty to AC, -2 penalty to attack rolls, +2 bonus to Combat Maneuver Bonus and Combat Maneuver Defense, and a -8 penalty to Stealth checks. A sand giant's lifting and carrying limits quadruple those of Medium characters. Space 15 ft., Reach 15 ft."},{"type":"Speed","value":"A sand giant's base speed is 50 ft."},{"type":"Low-light vision","value":"Sand giants can see twice as far as humans in conditions of dim light."},{"type":"Racial Hit Dice","value":"A sand giant starts with nineteen levels of humanoid, which provide it with 19d8 HD, a base attack bonus of +14, and base save bonuses of Fort +11, Ref +6, Will +6."},{"type":"Racial Skills","value":"A sand giant's giant levels give it skill points equal to 19 x (2 + Int modifier). Its class skill are Intimidate and Perception."},{"type":"Racial Feats","value":"A sand giant's giant levels give it 10 feats."},{"type":"AC","value":"+12 natural AC bonus."},{"type":"Special Attacks","value":"Fist of sand, spell-like abilities."},{"type":"Special Qualities","value":"Rock catching, scent."},{"type":"Weapon and Armor Proficiency","value":"Sand giants are automatically proficient with simple weapons, martial weapons, light and medium armor, and shields."},{"type":"Languages","value":"Sand giants begin play speaking Giant and Common. Sand giants with high intelligence scores can choose from the following languages: Draconic, Elven, Goblin, and Orc."}]}],"ecology":"","habitat_society":"","gear":"greatsword, studded leather armor"},{"name":"Very Old Gray Dragon","cr":14,"xp":38400,"alignment":"NE","size":"Huge","type":"dragon","subtypes":["water"],"init":4,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (270 ft., DC 22)"],"ac":36,"ac_touch":8,"ac_flat_footed":36,"ac_mods":"+28 natural, -2 size","hp":237,"hd":"19d12+114","hdvalue":19,"fort":17,"ref":13,"will":17,"immunities":["paralysis","sleep"],"sr":25,"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"2 claws +27 (2d6+10), bite +28 (2d8+15/19-20), 2 wings +25 (1d8+5), tail slap +25 (2d6+15)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"100-ft. line, 18d6 fire; DC 25 Ref half"}],"spellsknown_caster_level":11,"spellsknown_concentration":17,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"cloudkill"},{"spell":"telekinesis"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"dimension door"},{"spell":"greater invisibility"},{"spell":"scrying"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"gaseous form"},{"spell":"protection from energy"},{"spell":"ray of exhaustion"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blur"},{"spell":"eagle's splendor"},{"spell":"gust of wind"},{"spell":"locate object"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"burning hands"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"obscuring mist"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"ray of frost"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"touch of fatigue"}]}],"strength":31,"dexterity":10,"constitution":23,"intelligence":17,"wisdom":19,"charisma":17,"baseatk":19,"cmb":31,"cmd":41,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":25},{"skill":"Fly","value":18},{"skill":"Intimidate","value":25},{"skill":"Knowledge (local)","value":25},{"skill":"Perception","value":30},{"skill":"Sense Motive","value":30},{"skill":"Spellcraft","value":25},{"skill":"Stealth","value":14},{"skill":"Swim","value":40}],"languages":["Aquan","Common","Draconic","Giant Special Abilities"],"environments":["warm coastlines"],"organizations":["solitary"],"treasure":"triple standard","description_visual":"Steam emanates from the nostrils and mouth of this slate gray dragon.","group":"Dragon","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A gray dragon's breath weapon is a superheated line of steam."},{"type":"Change Shape","kind":"Su","details":"A young or older gray dragon can take any animal or humanoid form 3/day as if using polymorph."},{"type":"Corrupt Water","kind":"Sp","details":"Once per day an adult or older gray dragon can stagnate 10 cubic ft. of still water, making it foul and unable to support water-breathing life. The ability spoils liquids containing water. Liquid-based magic items (such as potions) and items in a creature's possession must succeed on a Will save (DC 19) or become ruined. This ability is the equivalent of a 1st-level spell. Its range is 180 ft."},{"type":"Spell-Like Abilities","kind":"Sp","details":"A gray dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. • Young-fog cloud; • Juvenile-create water; • Old-control winds; • Ancient-control water;"},{"type":"Water Breathing","kind":"Ex","details":"A gray dragon breathes water and can use its breath weapon, spells, and abilities underwater."}],"description":"Gray dragons are evil dragons that inhabit mountains and hills near coastlines. They have little regard for other races and often enslave others to do their bidding. Adult and older gray dragons are rarely found without a retinue of humanoid slaves. Gray dragons mate for life and a single mated pair often terrorizes nearby villages, laying waste to those that oppose the dragon's will.","ecology":"","habitat_society":""},{"name":"Volcano Giant","cr":14,"xp":38400,"alignment":"CN","size":"Huge","type":"humanoid","subtypes":["earth","fire","giant"],"init":1,"senses":[{"type":"low-light vision"}],"ac":29,"ac_touch":9,"ac_flat_footed":28,"ac_mods":"+2 armor, +1 Dex, +18 natural, -2 size","hp":201,"hd":"20d8+120","hdvalue":20,"fort":18,"ref":7,"will":9,"defensive_abilities":["rock catching"],"immunities":["fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":40}],"melee":"Gargantuan longspear +24 (4d6+16, crit x3) or 2 slams +24 (2d6+11)","ranged":"rock +15 (2d6+16 plus 1d6 fire)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon"},{"type":"rock throwing","details":"120 ft."},{"type":"trample","details":"2d6+16; DC 31"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"stone shape"}]}],"strength":32,"dexterity":12,"constitution":23,"intelligence":10,"wisdom":14,"charisma":11,"baseatk":15,"cmb":28,"cmd":39,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Bull Rush"},{"feat":"Improved Sunder"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":14,"special":"+18 jumping"},{"skill":"Climb","value":18},{"skill":"Intimidate","value":20},{"skill":"Knowledge (nature)","value":10},{"skill":"Perception","value":18}],"languages":["Giant","Ignan"],"sq":[{"type":"oversized weapon use"}],"environments":["warm mountains"],"organizations":["solitary","gang (2-5)","band (6-9 plus 35% noncombatants plus 1 adept or cleric of 1st or 2nd level)","hunting/raiding party (6-9 plus 1 adept or sorcerer of 3-5th level plus 3-8 fire lizards)","tribe (21-30 plus 1 adept, cleric, or sorcerer of 6th or 7th level plus 12-30 fire lizards)"],"treasure":"standard","description_visual":"This 18-foot tall, barrel-chested giant has leathery, reddish brown skin and haunting amber eyes. The creature is tough and wiry, with the strength and texture of copper.","group":"Giant","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Three times per day, a volcano giant can exhale a cloud of warm and sulfuric gas in a 30-foot cone. Affected creatures must make a successful DC 26 Fortitude save or take a -4 circumstance penalty on attack rolls, checks and saves for 1 minute (10 rounds) due to fits of coughing and choking. The save DC is Constitution-based."},{"type":"Oversized Weapon Use","kind":"Ex","details":"A volcano giant wields a Gargantuan two-handed longspear without penalty."}],"description":"Volcano giants make their homes in the many twisting caves and subterranean rooms of volcanic cones, enlarging and reinforcing them for comfort and convenience. Clothing for a volcano giant usually consists of little more than a simple wrap of fire lizard skin. A volcano giant wears ornaments made of bone, shell, and obsidian, and their general culture and society is similar to that of humanoid civilizations on tropical islands. Such island societies often get along well with local tribes of volcano giants, engaging in trade and peacefully coexisting. Should a tribe of volcano giants form an allegiance with a human tribe, the giants warn the humans of possible eruptions of their volcano to allow them time to escape the destruction. Although volcano giants can be described as good-natured and peaceful people, their demeanor can change quickly. At a real or imagined affront, a volcano giant can erupt with a passion that is rivaled only by the fire and fury of the volcano in which it lives. Volcano giants feel that their shadow is actually their soul, and don't tolerate any creature that dares to trod upon it. Volcano giants usually use Gargantuan longspears in combat. They are fierce and brave warriors, not backing down from any adversary. Many choose to open combat with their breath weapon so as to soften up their foes before attacking.","as_character":[{"description":"","racial_traits":[{"type":"Ability Score Bonuses","value":"+22 Strength, +2 Dexterity, +12 Constitution, +2 Wisdom: A volcano giant's prowess lies almost entirely in his physical abilities, predominantly strength."},{"type":"Huge","value":"Volcano giants are huge and take a -2 penalty to AC, -2 penalty to attack rolls, +2 bonus to Combat Maneuver Bonus and Combat Maneuver Defense, and a -8 penalty to Stealth checks. A volcano giant's lifting and carrying limits quadruple those of Medium characters. Space 15ft., Reach 15ft."},{"type":"Speed","value":"A volcano giant's base speed is 40 ft."},{"type":"Low-light vision","value":"volcano giants can see twice as far as humans in conditions of dim light."},{"type":"Racial Hit Dice","value":"A volcano giant starts with seventeen levels of giant, which provide it with 20d8 HD, a base attack bonus of +15, and base save bonuses of Fort +12, Ref +6, Will +6."},{"type":"Defensive Abilities","value":"a volcano giant gains the rock catching defensive ability."},{"type":"Racial Skills","value":"A volcano giant's giant levels give it skill points equal to 20 x (2 + Int modifier). Its class skills are Acrobatics, Climb, Intimidate, Knowledge (nature), and Perception."},{"type":"Racial Feats","value":"A volcano giant's giant levels give it ten feats."},{"type":"AC","value":"Tough-skinned, volcano giants gain a +18 natural AC bonus."},{"type":"Special Attacks","value":"Breath weapon, rock throwing, trample."},{"type":"Spell-like Abilities","value":"volcano giants can cast stone shape 1/day as a 20th level caster."},{"type":"Special Qualities","value":"fire and earth subtypes, low-light vision, oversized weapon use,"},{"type":"Automatic Languages","value":"Giant, Ignan. Volcano giants with high Intelligence scores can choose from the following languages: Draconic, Goblin, Terran, Orc."}]}],"ecology":"","habitat_society":"","gear":"Gargantuan longspear, leather armor"},{"name":"Vorin","cr":14,"xp":38400,"alignment":"CE","size":"Huge","type":"aberration","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+4 Dex, +6 natural, -2 size","hp":178,"hd":"17d8+102","hdvalue":17,"fort":11,"ref":9,"will":10,"dr":"15/slashing or piercing","immunities":["acid"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":40}],"melee":"sting +20 (2d6+9 plus poison), bite +19 (2d6+9)","ranged":"spit +15 (poison)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"spit"}],"strength":28,"dexterity":18,"constitution":23,"intelligence":2,"wisdom":11,"charisma":12,"baseatk":12,"cmb":23,"cmd":37,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (sting)"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Stealthy"},{"feat":"Weapon Focus (spit)"},{"feat":"Weapon Focus (sting)"}],"skills":[{"skill":"Escape Artist","value":6},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":2},{"skill":"Stealth","value":13,"special":"+21 in water"}],"sq":[{"type":"water breathing"}],"environments":["any marshes"],"organizations":["solitary","squad (2-5)"],"treasure":"standard","description_visual":"This creature is an immense greenish-black thing with intense yellow eyes. It is 30 ft. long and a foot thick. The body of the thing is a wormlike mass of pulpy flesh with several gill-like apertures along its length with which it propels itself through the water. The front of the beast has a long trunk similar to that of an elephant. Its skin glistens as if coated with a sheen of oil.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite or spit-injury or contact; save Fort DC 24; frequency 1/round for 2 rounds; effect 1d6 Dex and paralyzed 1d4 hours; cure 1 save. The save DC is Constitution-based. An opponent struck by a blob of vorin poison spit at them is protected from its effects for a short time by any amount of worn armor-the blob strikes the armor but not the opponent's flesh. The blob of poison seeps through armor in a number of rounds equal to the armor's armor bonus (don't apply any magical bonuses). The blob can be scraped off as a move action. Natural armor doesn't provide any defense as the poison seeps through the opponent's pores, nor does poison delivered by a vorin's sting have the same delayed effect."},{"type":"Spit","kind":"Ex","details":"Once per round a vorin can spit a blob of sticky poison with a sickening odor at a single opponent within 50 ft. (no range increment). This requires the vorin to make a successful ranged touch attack. If struck, a target is subjected to the vorin's poison."},{"type":"Water Breathing","kind":"Ex","details":"Vorins can breathe underwater indefinitely."}],"description":"Vorins live in dismal swamps and bogs, lurking down in the murk and the mire. The eyes of a vorin are raised above the rest of the head on slight bulges. This arrangement allows the vorin to remain mostly submerged while it watches its potential prey. A typical vorin is 30 ft. long and weighs 3,000 pounds.\n\nThe boneless body of a vorin helps to protect it from impacts. A vorin feeds and attacks with a long proboscis. This proboscis contains the creature's tongue, with is tipped with a thorny barb that can inject a paralytic poison. A vorin can also spit its poison at prey that it can't reach physically.\n\nA vorin relies on its poison in combat, hoping to incapacitate an opponent so it can consume the victim at its leisure. It enters combat by spitting poison at any larger opponents first. The vorin tries to remain at a distance, spitting its poison and darting back below the water to slither to another location before rising again. A vorin only enters melee if pressed or if it is unable to escape.","ecology":"","habitat_society":""},{"name":"Willow Dusk","cr":14,"xp":38400,"alignment":"CE","size":"Huge","type":"plant","init":-1,"senses":[{"type":"low-light vision"}],"ac":27,"ac_touch":7,"ac_flat_footed":27,"ac_mods":"-1 Dex, +20 natural, -2 size","hp":210,"hd":"20d8+120","hdvalue":20,"hp_mods":["fast healing 5"],"fort":17,"ref":7,"will":9,"dr":"10/magic","immunities":["plant traits"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":20}],"melee":"4 slams +23 (2d8+9 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"aura of misery"},{"type":"droning"},{"type":"swallow whole","details":"2d6+9 plus 1d8 acid damage, AC 19, 21 hp"}],"strength":29,"dexterity":8,"constitution":21,"intelligence":4,"wisdom":16,"charisma":10,"baseatk":15,"cmb":26,"cmb_special":"+2 vs. trip, +4 vs. grapple","cmd":35,"cmd_special":"+2 vs. trip","feats":[{"feat":"Ability Focus (aura of misery)"},{"feat":"Ability Focus (droning)"},{"feat":"Improved Trip"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":23},{"skill":"Stealth","value":6,"special":"+22 in forests"}],"languages":["Sylvan"],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"incidental","description_visual":"You see a 20 foot tall willow tree with dark greenish-brown branches and blackish-brown bark.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Aura of Misery","kind":"Su","details":"Once every 1d4+1 rounds as a free action, a willow dusk can emit a wave of negative energy that affects all living creatures within 10 ft. of it. Creatures within the area take 1d6 points of Charisma damage if they fail a DC 22 Will save. At Charisma 0, a creature collapses into a coma until at least 1 point of Charisma is restored. The save DC is Charisma-based."},{"type":"Droning","kind":"Su","details":"Once per round as a standard action, a willow dusk can emit a droning sound audible to a range of 100 ft. Creatures within the area that hear it, must succeed on a DC 22 Will save or enter a state of lethargy. Affected creatures cannot move (as if held by a hold monster spell) and have no desire to take any other action or engage in combat (unless attacked first, in which case the lethargy effect is broken). The effects last for a number of rounds equal to the one-half of the willow dusk's Hit Dice (10 rounds for the typical willow dusk). A willow dusk that attacks a creature affected by this ability gains a +4 bonus on its attack roll. Whether the attack succeeds or fails, the lethargy effect is immediately broken. A creature who succeeds on his Will save is unaffected by the droning from that same willow dusk for 24 hours. This is a mind-affecting effect. The save DC is Charisma-based."}],"description":"Willow dusks are nocturnal predators that drone their targets into a lethargic state or a coma-induced sleep before relentlessly attacking and devouring them. To the untrained eye, a willow dusk appears as a normal willow tree and nothing more. Any creature with 5 or more ranks in Knowledge (nature) or Survival can detect \"something's not quite right about that tree\" on a successful DC 20 check.\n\nA willow dusk prefers to devours a victim whole, scooping it up in its massive branches and dumping it fully into its gaping maw where its stomach acids digest its swallowed prey. Willow dusks prefer warmblooded creatures to cold-blooded creatures and always eat freshly killed prey. They are not scavengers and will not eat something they didn't kill (or at least something that has been dead longer than 1 hour).\n\nA willow dusk appears as a 20-foot tall willow tree and can grow to a height of 40 ft. or more. A typical willow dusk is 20 ft. tall and weighs 900 pounds.\n\nOccasionally, willow dusks have been known to aid evil-aligned druids and rangers.\n\nA willow dusk hunts at night, just as the sun is setting. When it finds a potential victim, it looses its droning and charges an opponent who succumbs to its effect, bashing it with a slam attack or grappling it and tossing it into its maw. Creatures who resist the willow dusk's droning are subjected to its aura of misery attack as long as they remain within 10 ft. of the creature. An opponent that falls to Charisma 0 is quickly scooped up by the willow dusk and devoured.","ecology":"","habitat_society":""},{"name":"Zombie Horde","cr":14,"xp":38400,"alignment":"NE","size":"Colossal","type":"undead","subtypes":["horde"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":2,"ac_flat_footed":13,"ac_mods":"+11 natural, -8 size","hp":110,"hd":"20d8 (+20)","hdvalue":20,"fort":6,"ref":6,"will":12,"defensive_abilities":["half damage from piercing weapons"],"dr":"10/slashing","immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"horde attack (6d6)","space":"30 ft.","reach":"5 ft.","special_attacks":[{"type":"feral rage"},{"type":"rend","details":"+3d6"}],"strength":22,"dexterity":10,"wisdom":10,"charisma":10,"baseatk":15,"cmb":29,"cmd":39,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Overrun","type":"bonus"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Stealth","value":-16}],"environments":["any"],"organizations":["solitary","mass (2-4 hordes)","apocalypse (5+ hordes)"],"treasure":"none","description_visual":"A stumbling crush of moaning, reaching bodies comes towards you. Empty eyes seek you out, each staggering footstep bringing the deathless mass closer. Straining to grasp you, this group of zombies are so tightly packed together it seems to be a single mass of undead, flailing limbs.","group":"Horde","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Feral Rage","kind":"Ex","details":"The horde attacks as a ruthless mob, intent only on tearing apart those that fall into their clutches. This frenzy prevents them from using any sort of tactics, and frees them from any form of control by other beings. However, the sheer force of the wave attack allows them to deal 6d6 points of damage to any creature whose space they occupy at the end of their move. This ability is lost if the horde is broken up."},{"type":"Horde Traits","kind":"Ex","details":"Hordes are not so called because of the size of the group but rather the size of the creatures that compose the horde. Unlike normal swarms, hordes are composed of Medium creatures which are usually a normal version of a creature but otherwise behave in a swarmlike manner. There are usually around 50 creatures in a horde. The net effect is that they take only half damage from piercing weapons but take normal damage from other weapons. In addition when the swarm is reduced to 0 hit points or lower and breaks up, unless the damage was dealt by area-affecting attacks, then 2d6 surviving members of the horde continue their attack, though now only as individual creatures. Otherwise, a horde conforms to all of the other swarm traits. Rend (EX) Due to the grasping and clawing nature of the zombie horde attack, any time the horde does more than 20 points of damage, add 3d6 slashing damage from the additional pulling and tearing. This ability is lost if the swarm is broken up."}],"description":"Zombies are one of the most used and abused of the mindless undead. Singly, a zombie may be dealt with by experienced adventurers. When gathered together in a horde, these mindless creatures are a terror to behold. Packed together as tightly as they are, they appear as one solid mass of decaying flesh and sinuous limbs.\n\nThe flailing nature of the zombie horde's limbs allow the throng to grasp and tear at opponents, dealing rend damage in addition to their base attack. Any time the horde is in an opponent's square, the target risks being completely overrun by the horde\n\nIf the horde takes enough individual damage to break it up, up to a dozen of the creatures continue on their rampage of destruction, until finally they too must be slain.","ecology":"","habitat_society":"","credit":"Originally appearing in Rappan Athuk (© Frog God Games, 2012)"},{"name":"Ancient Gray Dragon","cr":15,"xp":51200,"alignment":"NE","size":"Huge","type":"dragon","subtypes":["water"],"init":4,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (300 ft., DC 24)"],"ac":39,"ac_touch":8,"ac_flat_footed":39,"ac_mods":"+31 natural, -2 size","hp":283,"hd":"21d12+147","hdvalue":21,"fort":19,"ref":14,"will":19,"immunities":["paralysis","sleep"],"sr":26,"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"2 claws +30 (2d6+11), bite +31 (2d8+16/19-20), 2 wings +28 (1d8+5), tail slap +28 (2d6+11)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"100-ft. line, 20d6 fire; DC 27 Ref half"}],"spellsknown_caster_level":13,"spellsknown_concentration":20,"spellsknown":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"flesh to stone"},{"spell":"move earth"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"cloudkill"},{"spell":"telekinesis"},{"spell":"transmute rock to mud"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"dimension door"},{"spell":"greater invisibility"},{"spell":"scrying"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"gaseous form"},{"spell":"protection from energy"},{"spell":"ray of exhaustion"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blur"},{"spell":"eagle's splendor"},{"spell":"gust of wind"},{"spell":"locate object"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"burning hands"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"obscuring mist"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"light"},{"spell":"ray of frost"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"touch of fatigue"}]}],"strength":33,"dexterity":10,"constitution":25,"intelligence":19,"wisdom":21,"charisma":19,"baseatk":21,"cmb":34,"cmd":44,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":28},{"skill":"Fly","value":20},{"skill":"Intimidate","value":28},{"skill":"Knowledge (arcana)","value":28},{"skill":"Knowledge (local)","value":28},{"skill":"Perception","value":33},{"skill":"Sense Motive","value":33},{"skill":"Spellcraft","value":28},{"skill":"Stealth","value":16},{"skill":"Swim","value":43}],"languages":["Abyssal","Aquan","Common","Draconic","Giant Special Abilities"],"environments":["warm coastlines"],"organizations":["solitary"],"treasure":"triple standard","description_visual":"Steam emanates from the nostrils and mouth of this slate gray dragon.","group":"Dragon","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A gray dragon's breath weapon is a superheated line of steam."},{"type":"Change Shape","kind":"Su","details":"A young or older gray dragon can take any animal or humanoid form 3/day as if using polymorph."},{"type":"Corrupt Water","kind":"Sp","details":"Once per day an adult or older gray dragon can stagnate 10 cubic ft. of still water, making it foul and unable to support water-breathing life. The ability spoils liquids containing water. Liquid-based magic items (such as potions) and items in a creature's possession must succeed on a Will save (DC 19) or become ruined. This ability is the equivalent of a 1st-level spell. Its range is 180 ft."},{"type":"Spell-Like Abilities","kind":"Sp","details":"A gray dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. • Young-fog cloud; • Juvenile-create water; • Old-control winds; • Ancient-control water;"},{"type":"Water Breathing","kind":"Ex","details":"A gray dragon breathes water and can use its breath weapon, spells, and abilities underwater."}],"description":"Gray dragons are evil dragons that inhabit mountains and hills near coastlines. They have little regard for other races and often enslave others to do their bidding. Adult and older gray dragons are rarely found without a retinue of humanoid slaves. Gray dragons mate for life and a single mated pair often terrorizes nearby villages, laying waste to those that oppose the dragon's will.","ecology":"","habitat_society":""},{"name":"Beluiri (The Temptress)","cr":15,"xp":51200,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"true seeing"}],"ac":40,"ac_touch":25,"ac_flat_footed":32,"ac_mods":"+7 Dex, +1 dodge, +15 natural, +7 profane","hp":184,"hd":"16d10+96","hdvalue":16,"fort":16,"ref":14,"will":17,"dr":"15/cold iron and good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":26,"speed":[{"type":"land","speed":40}],"melee":"2 claws +22 (1d6+6 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"dominating gaze"},{"type":"seduction"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"blasphemy"},{"spell":"charm monster"},{"spell":"deeper darkness"},{"spell":"desecrate"},{"spell":"detect good"},{"spell":"detect law"},{"spell":"fear"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"polymorph self"},{"spell":"tongues","details":"self only"},{"spell":"unhallow"}]},{"frequency":"1/day","spells":[{"spell":"fire storm"},{"spell":"summon","details":"level 9, 1d4 hezrous or 1d4 gharros demons, 100%"},{"spell":"wail of the banshee"}]},{"frequency":"3/day","spells":[{"spell":"greater dispel magic"},{"spell":"suggestion"},{"spell":"wall of fire"}]}],"strength":22,"dexterity":24,"constitution":22,"intelligence":20,"wisdom":20,"charisma":24,"baseatk":16,"cmb":22,"cmd":47,"feats":[{"feat":"Ability Focus (seduction)"},{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Bluff","value":30},{"skill":"Diplomacy","value":26},{"skill":"Disguise","value":27},{"skill":"Escape Artist","value":18},{"skill":"Intimidate","value":26},{"skill":"Knowledge (arcana)","value":21},{"skill":"Knowledge (planes)","value":24},{"skill":"Perception","value":36},{"skill":"Sense Motive","value":28},{"skill":"Stealth","value":26},{"skill":"Survival","value":21}],"languages":["Abyssal","Celestial","Common","Goblin","Infernal"],"environments":["any (Abyss)"],"organizations":["solitary","troupe (Beluiri plus 1d4 hezrous or 1d4 gharros demons)"],"treasure":"double standard","description_visual":"This creature appears as a bronze-skinned female standing about 6 ft. tall. Its head is hairless and features four downward-curving horns jutting just above its forehead. The two lower horns are smaller than the topmost horns. A ridge of small spines runs from the creature's brow down the center of its head and tapers off just below its shoulder blades.  Its hands end in razor-sharp talons and its eyes are sapphire blue.","group":"Demon Lord","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Dominating Gaze","kind":"Su","details":"Three times per day, 30 ft., DC 25 Will save or dominated as per the dominate person spell (CL 20th). The save DC is Charisma-based."},{"type":"Poison","kind":"Ex","details":"Claw-injury; save Fort DC 24; frequency 1 round for 4 rounds; effect 1d4 Str damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Seduction","kind":"Su","details":"Through body language and movement, Beluiri can fascinate all creatures of the opposite sex (which could be either sex, depending on her current form) within 30 ft. that observe her dancing. Those viewing this dance must succeed on a DC 27 Will save or fall under her influence for 1d6+1 hours as if affected by a charm monster spell (CL 20th). The save DC is Charisma-based and includes a +2 bonus from her Ability Focus feat."}],"description":"Beluiri is one of the many concubines of Lord Baphomet (and one of his favorites). She is known throughout the Abyss as the Temptress, for in her many disguises she has seduced countless princes, lords, and generals of the Abyss. In the end, she most often betrays those that fall victim to her wiles. She is hated for this by more than one noble or lord of the Abyss. She sometimes journeys to the Material Plane (in one of her many guises) to tempt and seduce mortals, for she knows that all mortals, in their hearts, always give in to their true desires-be it power, greed, lust, or one of many countless other sins.\n\nBeluiri rarely wears clothing, but at times when she does, she enjoys gowns and robes of gold, white, and red.\n\nBeluiri prefers subterfuge rather than directly assaulting an opponent.\n\nShe usually alters her appearance to appear as an attractive member of a potential victim's race; once the victim is lured in, she assumes her true form and attacks. If combat goes against her, she flees, but only after summoning lesser demons to cover her escape and kill her opponents.","ecology":"","habitat_society":""},{"name":"Cat Lord","cr":15,"xp":51200,"alignment":"N","size":"Medium","type":"outsider","subtypes":["native","shapechanger"],"init":11,"senses":[{"type":"darkvision","modifier":"200 ft."},{"type":"detect evil"},{"type":"detect good"},{"type":"keen senses"},{"type":"low-light vision"}],"ac":32,"ac_touch":20,"ac_flat_footed":25,"ac_mods":"+7 Dex, +12 natural, +3 insight","hp":199,"hd":"19d10+95","hdvalue":19,"fort":16,"ref":20,"will":7,"defensive_abilities":["feline passivism","immortality"],"dr":"20/magic and cold iron","immunities":["mind-affecting effects","psionics"],"sr":26,"speed":[{"type":"land","speed":60},{"type":"climb","speed":30}],"melee":"2 claws +27 (1d6+7 plus grab), bite +26 (1d8+7)","ranged":"spit +26 (blindness)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"howl"},{"type":"pounce"},{"type":"rake","details":"2 claws +27, 1d6+7"}],"spell_like_abilities_caster_level":19,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"detect good"},{"spell":"speak with animals","details":"felines only"}]},{"frequency":"at-will","spells":[{"spell":"blur"},{"spell":"greater invisibility"},{"spell":"hypnotism"}]},{"frequency":"1/day","spells":[{"spell":"astral projection"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"}]},{"frequency":"2/day","spells":[{"spell":"ethereal jaunt"},{"spell":"haste","details":"self only"},{"spell":"summon","details":"level 6, 1d4+2 lions or tigers, or 1d4+4 leopards or cheetahs, or 1d2 dire lions, dire tigers, or weretigers, or 30 + 1d20 normal cats 100%"}]},{"frequency":"9/day","spells":[{"spell":"dimension door"},{"spell":"lick wounds","details":"self only; heals 2d4 damage"}]}],"strength":24,"dexterity":25,"constitution":20,"intelligence":19,"wisdom":17,"charisma":20,"baseatk":19,"cmb":17,"cmb_special":"+4 vs. grapple","cmd":34,"feats":[{"feat":"Acrobatic"},{"feat":"Alertness"},{"feat":"Athletic"},{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Acrobatics","value":38,"special":"+50 when jumping"},{"skill":"Climb","value":38},{"skill":"Escape Artist","value":26},{"skill":"Fly","value":9},{"skill":"Handle Animal","value":24},{"skill":"Heal","value":22},{"skill":"Knowledge (nature)","value":23},{"skill":"Perception","value":29},{"skill":"Sense Motive","value":29},{"skill":"Stealth","value":37},{"skill":"Survival","value":22},{"skill":"Swim","value":9}],"languages":["Common","Sylvan","Druidic","Elven","Goblin","Gnome","telepathy 100 ft."],"sq":[{"type":"change shape","details":"human and panther, polymorph"}],"environments":["temperate forests"],"organizations":["solitary","troupe (Cat Lord plus 3-6 lions or tigers, or 5-8 cheetahs)"],"treasure":"double standard","description_visual":"This creature resembles a great black panther with ruby eyes.","group":"Cat Lord","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Change Shape","kind":"Su","details":"The Cat Lord can assume the shape of a human as a standard action. In human form, the Cat Lord cannot use his natural weapons or his howl, pounce, spit, or rake special attacks but can wield weapons and wear armor. Unlike the normal change shape ability, the Cat Lord retains his movement modes (and speeds) in human form."},{"type":"Feline Passivism","kind":"Ex","details":"Felines (including dire versions) don't willingly attack the Cat Lord, though they can be forced to do so by magic. If the Cat Lord attacks a feline, its protection against that creature ends."},{"type":"Howl","kind":"Su","details":"When the Cat Lord howls, all creatures except felines within a 20-foot spread must succeed on a DC 24 Will save or be stunned for 1d2 rounds. A creature that successfully saves cannot be affected again by the Cat Lord's howl for one day. The save DC is Constitution-based."},{"type":"Immortality","kind":"Su","details":"The Cat Lord is effectively immortal and nearly impossible to slay. When slain, the Cat Lord's soul reforms on the Astral Plane. Within 9 days, it inhabits another feline on the Material Plane and the Cat Lord reforms. No form of magic (such as magic that would contain or trap his soul) prevents this. To permanently kill the Cat Lord, it is thought that one must destroy every feline in existence (so his soul has no creature to inhabit)."},{"type":"Keen Senses","kind":"Ex","details":": The Cat Lord sees five times as well as a human in shadowy illumination and normal light."},{"type":"Spit","kind":"Ex","details":"Once every 1d4 rounds as a ranged attack, the Cat Lord can spit a line of caustic saliva at a single target to a range of 30 ft. A creature hit must succeed on a DC 24 Reflex save or be blinded. Remove blindness or dispel magic (vs. CL 19th) removes the blindness effect. The save DC is Constitution-based."}],"description":"There is only one. The Cat Lord is the Lord of All Felines. His natural form is that of a black panther with dark, ruby eyes. He can assume a human form, and in this form, he appears as a dark-skinned human with black hair, chiseled features, and ruby eyes. In human form, he stands 6 ft. tall and he almost always dresses in black. The Cat Lord spends his days roaming the Material Plane, Astral Plane, and Ethereal Plane. In combat, the Cat Lord almost always assumes feline form (if he's not already in that form) and attacks with two claws and a bite. The Cat Lord often enters combat with both haste and blur in effect. If combat goes against him, he usually summons a group of felines to his aid or to cover his escape.","ecology":"","habitat_society":"","credit":"The Cat Lord originally appeared in Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."}];
